// Des: Tests the feed reader: records from a fake group feed
// Flo: pure helpers > read mode prints counts and writes nothing > live writes one atomic .jsonl with the record fields
// I/O: mock site + temp dir > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const rigz = @import("te-rigz-brow.zig"); const feed = @import("ru-feed-reco.zig"); const rdm = @import("ru-read-main.zig"); const cfgz = @import("cf-conf-load.zig");
fn has(rig: *rigz.Rig, needle: []const u8) bool { return std.mem.find(u8, rig.sink.items, needle) != null; }
test "post id comes from the permalink, query and fragment are cut" { try std.testing.expectEqualStrings("555001", feed.idOfUrl("/groups/12/posts/555001/?ref=x")); try std.testing.expectEqualStrings("77", feed.idOfUrl("https://www.facebook.com/groups/1/permalink/77/")); try std.testing.expectEqualStrings("9", feed.idOfUrl("/marketplace/item/9#a")); try std.testing.expectEqualStrings("", feed.idOfUrl("/groups/12/")); }
test "record: needs a permalink and text, url is absolute, text is capped, author trimmed" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const conf: cfgz.Conf = .{}; const rec = (try feed.recoOf(aren.allocator(), conf, "/groups/12/", .{ .u = "/groups/12/posts/555001/?ref=x", .a = " Ann ", .t = "Toyota 2017 0966.353.678" })).?; try std.testing.expectEqualStrings("face", rec.kind); try std.testing.expectEqualStrings("555001", rec.id); try std.testing.expectEqualStrings("https://www.facebook.com/groups/12/posts/555001", rec.url); try std.testing.expectEqualStrings("Ann", rec.auth); try std.testing.expectEqualStrings("/groups/12/", rec.src); try std.testing.expectEqualStrings("private", rec.role); try std.testing.expect(std.mem.find(u8, rec.text, "0966.353.678") != null); try std.testing.expect((try feed.recoOf(aren.allocator(), conf, "/g/", .{ .u = "", .t = "x" })) == null); try std.testing.expect((try feed.recoOf(aren.allocator(), conf, "/g/", .{ .u = "/p/posts/1/", .t = "  " })) == null); var small = conf; small.feed_text_maxz = 200; const long: [500]u8 = @splat('a'); const cut = (try feed.recoOf(aren.allocator(), small, "/g/", .{ .u = "/p/posts/1/", .t = &long })).?; try std.testing.expect(cut.text.len <= 200); const abso = (try feed.recoOf(aren.allocator(), conf, "/g/", .{ .u = "https://www.facebook.com/x/posts/5/?a=1", .t = "t" })).?; try std.testing.expectEqualStrings("https://www.facebook.com/x/posts/5", abso.url); }
test "config: feed keys have safe defaults and bad values are refused" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const conf: cfgz.Conf = .{}; try std.testing.expectEqual(@as(usize, 0), conf.feed_path_list.len); try std.testing.expectEqual(@as(u32, 50), conf.feed_item_maxz); const good = try cfgz.confParse(aren.allocator(), "{\"feed_path_list\": [\"/groups/12/\"]}"); try std.testing.expectEqual(@as(usize, 1), good.feed_path_list.len); const bads = [_][]const u8{ "{\"feed_path_list\": [\"groups/12\"]}", "{\"feed_path_list\": [\"\"]}", "{\"feed_item_maxz\": 0}", "{\"feed_item_maxz\": 501}", "{\"feed_text_maxz\": 10}" }; for (bads) |badz| try std.testing.expectError(error.BadConfig, cfgz.confParse(aren.allocator(), badz)); }
test "feed read: dry prints counts and writes nothing; live writes one jsonl for scra; no paths is zero" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.read); try std.testing.expectEqual(@as(u32, 0), try rdm.readRun(&cx, "feed")); try std.testing.expect(has(&rig, "no feed_path_list")); rig.conf.feed_path_list = &.{"/feeds/12/"}; cx = rig.ctx(.read); try std.testing.expectEqual(@as(u32, 2), try rdm.readRun(&cx, "feed")); try std.testing.expect(has(&rig, "2 records, 1 skipped | add --live")); var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; const dirz = try std.fmt.bufPrint(&buff, ".zig-cache/tmp/{s}/social-in", .{tmpz.sub_path}); cx = rig.ctx(.read); cx.feedd = dirz; _ = try rdm.readRun(&cx, "feed"); try std.testing.expectError(error.FileNotFound, std.Io.Dir.cwd().openDir(std.testing.io, dirz, .{}));
    cx = rig.ctx(.live); cx.feedd = dirz; try std.testing.expectEqual(@as(u32, 2), try rdm.readRun(&cx, "feed")); try std.testing.expect(has(&rig, "wrote 2 records to")); var dir = try std.Io.Dir.cwd().openDir(std.testing.io, dirz, .{ .iterate = true }); defer dir.close(std.testing.io); var found: u32 = 0; var iter = dir.iterate(); var body: []u8 = &.{}; var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); while (try iter.next(std.testing.io)) |ent| { try std.testing.expect(std.mem.endsWith(u8, ent.name, ".jsonl")); found += 1; body = try dir.readFileAlloc(std.testing.io, ent.name, aren.allocator(), .limited(1 << 20)); } try std.testing.expectEqual(@as(u32, 1), found); var lines: u32 = 0; var splz = std.mem.splitScalar(u8, body, '\n'); while (splz.next()) |line| { if (line.len == 0) continue; lines += 1; const rec = try std.json.parseFromSliceLeaky(feed.Reco, aren.allocator(), line, .{ .ignore_unknown_fields = true }); try std.testing.expectEqualStrings("face", rec.kind); try std.testing.expect(std.mem.endsWith(u8, rec.url, "/groups/12/posts/555001") or std.mem.endsWith(u8, rec.url, "/groups/12/posts/555002")); try std.testing.expectEqualStrings("/feeds/12/", rec.src); try std.testing.expect(rec.auth.len > 0); } try std.testing.expectEqual(@as(u32, 2), lines); try std.testing.expect(std.mem.find(u8, body, "0966.353.678") != null); try std.testing.expect(std.mem.find(u8, body, "Nguyen Van A") != null); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); }
